enum PromptSubmitStatus: Codable, Hashable, Sendable, CaseIterable, RawRepresentable {
    case streaming
    case queued
    case steered
    case redirected
    /// A value this contract doesn't know, kept as sent.
    case unknown(String)

    static let allCases: [PromptSubmitStatus] = [.streaming, .queued, .steered, .redirected]

    init(rawValue: String) {
        switch rawValue {
        case "streaming": self = .streaming
        case "queued": self = .queued
        case "steered": self = .steered
        case "redirected": self = .redirected
        default: self = .unknown(rawValue)
        }
    }

    var rawValue: String {
        switch self {
        case .streaming: return "streaming"
        case .queued: return "queued"
        case .steered: return "steered"
        case .redirected: return "redirected"
        case let .unknown(value): return value
        }
    }

    init(from decoder: Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

